    const searchButton=document.createElement('button');searchButton.dataset.action='search';searchButton.textContent='搜索';this.action('upload').before(searchButton);this.searchDialog=document.createElement('dialog');this.searchDialog.innerHTML=`<form><h2>搜索文件</h2><label>方式<select data-role="search-mode"><option value="1">where.exe（原始输出）</option><option value="2">Windows 索引服务</option><option value="3">通常搜索（递归）</option></select></label><label>名称或模式<input data-role="search-query" required placeholder="例如 *.log 或 ZPigeon"></label><p data-role="search-status" class="status"></p><pre data-role="search-output"></pre><div class="dialog-actions"><button type="button" data-action="close-search">关闭</button><button type="submit">搜索</button></div></form>`;host.append(this.searchDialog);
