  render(){this.body.replaceChildren();for(const item of this.records){const row=document.createElement('tr');row.innerHTML='<td></td><td></td><td></td><td></td>';row.children[0].textContent=item.name;row.children[1].textContent=date(item.lastWriteTime);row.children[2].textContent=item.attributes&DIRECTORY?'文件夹':'文件';fileSize(row.children[3],item);row.onclick=()=>this.select(row,item);row.ondblclick=()=>{if(item.attributes&DIRECTORY)this.open(join(this.path,item.name),this.nodes.get(join(this.path,item.name).toLocaleLowerCase()))};row.oncontextmenu=event=>this.context(event,row,item);this.body.append(row)}this.empty.hidden=this.records.length!==0;this.empty.textContent='此文件夹为空'}
