  renderNode(node){const li=document.createElement('li'),row=document.createElement('div'),arrow=document.createElement('button'),label=document.createElement('button'),children=document.createElement('ul');row.className='file-node-row';arrow.className='file-arrow';arrow.textContent=node.hasChildren?'▸':'';arrow.disabled=!node.hasChildren;arrow.tabIndex=-1;label.className='file-node-label';label.textContent=node.name;label.title=node.path;children.hidden=true;row.append(arrow,label);li.append(row,children);node.row=row;node.arrow=arrow;node.label=label;node.children=children;arrow.onclick=event=>{event.stopPropagation();this.toggle(node)};label.onclick=()=>this.open(node.path,node);row.oncontextmenu=event=>this.treeContext(event,node);return li}
