  async info(path=this.selected&&join(this.path,this.selected.name),title=this.selected?.name){if(!path)return;try{const root=/^[A-Za-z]:\\$/.test(path),body=this.host.querySelector('[data-role=details-body]'),attributesBox=this.host.querySelector('[data-role=attributes-box]'),volumeBox=this.host.querySelector('[data-role=volume]');if(root){const value=await this.call('/api/file/volume',{path});this.property={path,volume:true,label:value.label};body.replaceChildren(...details([['路径',path],['类型','本地磁盘'],['文件系统',value.fileSystem],['容量',bytes(value.totalBytes)],['可用空间',bytes(value.freeBytes)],['已用空间',bytes(value.totalBytes-value.freeBytes)],['卷序列号',value.serialNumber.toString(16).padStart(8,'0').toUpperCase()]]));this.host.querySelector('[data-role=volume-label]').value=value.label;attributesBox.hidden=true;volumeBox.hidden=false}else{const value=await this.call('/api/file/info',{path}),directory=!!(value.attributes&DIRECTORY),fields=[['路径',path],['类型',directory?'文件夹':'文件'],['大小',directory?'':bytes(value.size)],['创建时间',date(value.creationTime)],['修改时间',date(value.lastWriteTime)],['访问时间',date(value.lastAccessTime)]],attributes=directory?FILE_ATTRIBUTES.filter(([flag])=>flag===0x2):FILE_ATTRIBUTES;this.property={path,directory};body.replaceChildren(...details(fields));this.host.querySelector('[data-role=attributes]').replaceChildren(...attributes.map(([flag,name])=>{const label=document.createElement('label'),input=document.createElement('input');label.className='file-attribute';input.type='checkbox';input.value=flag;input.checked=!!(value.attributes&flag);label.append(input,name);return label}));attributesBox.hidden=false;volumeBox.hidden=true}this.host.querySelector('[data-role=details-title]').textContent=title;this.detailsDialog.showModal()}catch(e){this.notify(e)}}
  async saveProperties(){if(!this.property)return;try{if(this.property.volume){const label=this.host.querySelector('[data-role=volume-label]').value;if(label!==this.property.label)await this.call('/api/file/volume/label',{path:this.property.path,label})}else{let attributes=0;for(const input of this.host.querySelectorAll('[data-role=attributes] input:checked'))attributes|=Number(input.value);await this.call('/api/file/attributes',{path:this.property.path,attributes})}this.detailsDialog.close();await this.open(this.path,this.currentNode,true)}catch(e){this.notify(e)}}
