  async hash(algorithm,name){if(!this.selected)return;this.menu.hidden=true;const path=join(this.path,this.selected.name),status=this.host.querySelector('[data-role=hash-status]'),output=this.host.querySelector('[data-role=hash-value]'),copy=this.action('copy-hash');this.host.querySelector('[data-role=hash-title]').textContent=`${name} · ${this.selected.name}`;status.textContent='正在计算…';output.value='';copy.disabled=true;this.hashDialog.showModal();try{const value=await this.call('/api/file/hash',{path,algorithm});status.textContent='计算完成';output.value=value.value;copy.disabled=false}catch(e){status.textContent=e.message}}
