    this.body=host.querySelector('tbody');this.empty=host.querySelector('.manager-empty');this.filter=host.querySelector('[data-role=filter]');this.menu=host.querySelector('[data-role=menu]');this.dialog=host.querySelector('[data-role=details]');this.dialog.onclose=()=>{this.dialog.querySelector('[data-field=password]').value=this.dialog.querySelector('[data-field=passwordConfirm]').value=''};this.filter.oninput=()=>{this.serviceNames=null;this.render()};for(const button of host.querySelectorAll('.service-menu [data-action]'))button.onclick=()=>this.invoke(button.dataset.action);for(const button of this.dialog.querySelectorAll('[data-tab]'))button.onclick=()=>this.tab(button.dataset.tab);for(const button of this.dialog.querySelectorAll('[data-control]'))button.onclick=()=>this.control(Number(button.dataset.control));for(const field of this.dialog.querySelectorAll('[data-config]'))field.oninput=()=>{field.dataset.changed='1';this.dirty(field.dataset.config);this.updatePropertyOptions()};this.action('close',this.dialog).onclick=()=>this.dialog.close();this.action('cancel',this.dialog).onclick=()=>this.dialog.close();this.action('apply',this.dialog).onclick=()=>this.apply();this.action('ok',this.dialog).onclick=async()=>{if(await this.apply())this.dialog.close()};addEventListener('click',event=>{if(!this.menu.contains(event.target))this.menu.hidden=true});addEventListener('blur',()=>this.menu.hidden=true);
